    for (int i = 0; i < 8; ++i) { const int r = rb + 2 * i; sOff[i] = r * 128 + ((jj ^ (r & 7)) << 4) + (c4 & 1) * 8; }
    uint64_t pol;
    asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    const uint32_t fullL = mapa0(smem_u32(&full[0]));
    float4 buf[8];
    load_kb(buf, src, g, pol);
    for (int j = 0; j < p.nb; ++j) {
      if (kCvtDrain && j > 0) { drain(j - 1, accum, 0, 0, p.n1, dh, dnh); release_acc(tfree); }
      for (int kb = g; kb < kKB; kb += kGroups) {
        const int t = j * kKB + kb, s = t % p.stages;
        if (t >= p.stages) mbar_wait(smem_u32(&empty[s]), ((t / p.stages) - 1) & 1);
        else if (p.fuse) mbar_wait(smem_u32(&sfree), 0);
        const uint32_t a = sbase + s * stageBytes;
#pragma unroll
        for (int i = 0; i < 8; ++i) { const float4 x = buf[i]; sts64(a + sOff[i], pack_h2(x.x, x.y), pack_h2(x.z, x.w)); }
        asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
        asm volatile("bar.sync %0, %1;" ::"r"(1 + g), "r"(32 * kGroupWarps) : "memory");
        if (w == 0) { if (elect_one()) arrive_cluster(fullL + 8 * s); __syncwarp(); }
        if (kb + kGroups < kKB) load_kb(buf, src, kb + kGroups, pol);
        else if (kCvtDrain && j + 1 < p.nb) { src = W + (size_t)(m0_of(j + 1) + rb) * kD + c4 * 4; load_kb(buf, src, g, pol); }
        if (kCvtDrain && j > 0 && kb == g) { drain(j - 1, accum1, p.n1, p.n1, p.n2, dh, dnh); release_acc(tfree1); }
      }
      if (!kCvtDrain && j + 1 < p.nb) {
        src = W + (size_t)(m0_of(j + 1) + rb) * kD + c4 * 4;
        load_kb(buf, src, g, pol);
        if (!kEpi) {
          epilogue(j, cw >> 2, kCvtWarps / 4);
          asm volatile("tcgen05.fence::before_thread_sync;");
          asm volatile("bar.sync %0, %1;" ::"r"(1 + kGroups), "r"(32 * kCvtWarps) : "memory");
          TLX(cw == 0 && lane == 0, 6);
          if (cw == 0) { if (elect_one()) arrive_cluster(mapa0(smem_u32(&tfree))); __syncwarp(); }
        }
      }
    }
  }
  if (kEpi && warp >= kEpiWarp0) {
    for (int j = 0; j + 1 < p.nb; ++j) {
      drain(j, accum, 0, 0, p.n1, dh, dnh);
      TLX(warp == kEpiWarp0 && lane == 0 && j == 0, 6);
      release_acc(tfree);
      drain(j, accum1, p.n1, p.n1, p.n2, dh, dnh);
      TLX(warp == kEpiWarp0 && lane == 0 && j == 0, 7);
      release_acc(tfree1);
    }
  }
  if (kEpi) {
    if (warp >= kCvtWarp0) {
      const int jl = p.nb - 1, h = (warp - kCvtWarp0) >> 2, nh = (kCvtWarps + kEpiWarps) / 4;
      drain(jl, accum, 0, 0, p.n1, h, nh);
      drain(jl, accum1, p.n1, p.n1, p.n2, h, nh);
    }
  } else {
    if (p.nb == 1) epilogue(0, warp >> 2, kThreads / 128);
    else if (warp >= kCvtWarp0) epilogue(p.nb - 1, (warp - kCvtWarp0) >> 2, kCvtWarps / 4);
  }
  TLX(warp == kCvtWarp0 && lane == 0, 13);
  asm volatile("tcgen05.fence::before_thread_sync;");
  cluster_sync();
  TLX(threadIdx.x == 0, 14);
  if (warp == 3) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(p.tmem_cols));
  }
